// A Tune In playlist may only be generated by the one request that followed
// an accepted session start. This keeps duplicate UI/bridge retries harmless.
export function isAcceptedTuneIn({ requestId = null, pendingRequestId = '' } = {}) {
  return Boolean(
    (requestId && pendingRequestId === requestId) ||
    (!requestId && pendingRequestId === '__unpaired__'),
  );
}
